import { execFile } from 'node:child_process';
import fs from 'node:fs/promises';
import path from 'node:path';
import { z } from 'zod';

import { trustGithubRepo } from './agent-deployment.js';
import { CLAIM_INSTRUCTIONS } from './deploy-instructions.js';
import { agentSiteUrl, prepareAgentDeployment, type DeployOptions } from './deploy.js';

const githubRepoSchema = z.object({
  id: z.number().int().positive(),
  full_name: z.string().regex(/^[\w.-]+\/[\w.-]+$/),
  default_branch: z.string().min(1),
});

export type GithubRepo = z.infer<typeof githubRepoSchema>;

export const GITHUB_WORKFLOW_PATH = path.join('.github', 'workflows', 'mintlify.yml');

function run(command: string, args: string[], cwd: string): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile(command, args, { cwd }, (error, stdout) =>
      error ? reject(error) : resolve(String(stdout).trim())
    );
  });
}

export function parseGithubRemote(remote: string): { owner: string; repo: string } | null {
  const match = remote
    .trim()
    .match(
      /^(?:https:\/\/(?:[^@/]+@)?github\.com\/|ssh:\/\/git@github\.com(?::\d+)?\/|git@github\.com:)([\w.-]+)\/([\w.-]+?)(?:\.git)?\/?$/
    );
  return match?.[1] && match[2] ? { owner: match[1], repo: match[2] } : null;
}

export function githubWorkflow(branch: string, subdomain: string, docsPath = ''): string {
  const directory = /^[\w./-]+$/.test(docsPath) ? docsPath : JSON.stringify(docsPath);
  return [
    'name: Deploy to Mintlify',
    'on:',
    '  push:',
    `    branches: [${JSON.stringify(branch)}]`,
    ...(docsPath
      ? [`    paths: [${JSON.stringify(`${docsPath}/**`)}, ".github/workflows/mintlify.yml"]`]
      : []),
    'permissions:',
    '  id-token: write',
    '  contents: read',
    'concurrency:',
    '  group: mintlify-deploy',
    '  cancel-in-progress: true',
    'jobs:',
    '  deploy:',
    '    runs-on: ubuntu-latest',
    '    steps:',
    '      - uses: actions/checkout@v4',
    `      - run: npx mint@latest deploy --subdomain ${subdomain}${docsPath ? ` --directory ${directory}` : ''}`,
    '',
  ].join('\n');
}

async function readFileIfExists(file: string): Promise<string | undefined> {
  return fs.readFile(file, 'utf8').catch((error: NodeJS.ErrnoException) => {
    if (error.code === 'ENOENT') return undefined;
    throw error;
  });
}

export async function writeGithubWorkflow(
  root: string,
  contents: string,
  force = false
): Promise<'created' | 'unchanged' | 'updated'> {
  const file = path.join(root, GITHUB_WORKFLOW_PATH);
  const existing = await readFileIfExists(file);
  if (existing === contents) return 'unchanged';
  if (existing !== undefined && !force) {
    throw new Error(
      `${GITHUB_WORKFLOW_PATH} already exists with different contents. Pass --force to overwrite it.`
    );
  }
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, contents);
  return existing === undefined ? 'created' : 'updated';
}

export async function findGitRoot(directory: string): Promise<string> {
  try {
    return await run('git', ['rev-parse', '--show-toplevel'], directory);
  } catch {
    throw new Error('--github requires a Git repository. Run it inside your docs repository.');
  }
}

export async function resolveGithubRepo(root: string): Promise<GithubRepo> {
  const remote = await run('git', ['remote', 'get-url', 'origin'], root).catch(() => {
    throw new Error('This repository has no origin remote. Add a github.com origin and retry.');
  });
  const parsed = parseGithubRemote(remote);
  if (!parsed) throw new Error(`The origin remote (${remote}) is not a github.com repository.`);
  const output = await run(
    'gh',
    [
      'api',
      `repos/${parsed.owner}/${parsed.repo}`,
      '--jq',
      '{id: .id, full_name: .full_name, default_branch: .default_branch}',
    ],
    root
  ).catch((error: NodeJS.ErrnoException) => {
    if (error.code === 'ENOENT')
      throw new Error('The GitHub CLI (gh) is required. Install it and run `gh auth login`.');
    throw new Error(
      `Could not read ${parsed.owner}/${parsed.repo} with gh. Run \`gh auth login\` with access to the repository and retry.`
    );
  });
  try {
    return githubRepoSchema.parse(JSON.parse(output));
  } catch {
    throw new Error('gh returned an unexpected repository response.');
  }
}

export type GithubSetupResult = {
  siteUrl: string;
  subdomain: string;
  repository: string;
  branch: string;
  workflowPath: string;
  workflow: 'created' | 'unchanged' | 'updated';
};

export async function setupGithubDeployment(
  options: DeployOptions & { force?: boolean },
  warn: (message: string) => void,
  progress: (message: string) => void = () => {}
): Promise<GithubSetupResult> {
  const directory = path.resolve(options.directory);
  const root = await findGitRoot(directory);
  const [realRoot, realDirectory] = await Promise.all([fs.realpath(root), fs.realpath(directory)]);
  const docsPath = path.relative(realRoot, realDirectory).split(path.sep).join('/');
  if (!(await readFileIfExists(path.join(directory, 'docs.json')))) {
    throw new Error(`No docs.json in ${directory}. Pass the docs folder with --directory.`);
  }
  progress('Resolving the GitHub repository...');
  const repo = await resolveGithubRepo(root);
  const result = await prepareAgentDeployment(options, warn, progress);
  if (result.status === 'claimed') {
    throw new Error(
      'This site has been claimed. Setting up GitHub deploys for claimed sites is not supported yet; connect the repository from the Mintlify dashboard.'
    );
  }
  const accessToken = result.credentials.accessToken;
  if (!accessToken) throw new Error('Agent authentication did not return an access token.');
  progress(`Trusting ${repo.full_name}@${repo.default_branch} to deploy...`);
  await trustGithubRepo(options.apiUrl, accessToken, {
    repositoryId: String(repo.id),
    repository: repo.full_name,
    branch: repo.default_branch,
  });
  const workflow = await writeGithubWorkflow(
    root,
    githubWorkflow(repo.default_branch, result.site.subdomain, docsPath),
    options.force
  );
  return {
    siteUrl: agentSiteUrl(options.apiUrl, result.site.subdomain),
    subdomain: result.site.subdomain,
    repository: repo.full_name,
    branch: repo.default_branch,
    workflowPath: GITHUB_WORKFLOW_PATH,
    workflow,
  };
}

export function formatGithubSetup(result: GithubSetupResult): string {
  return [
    `Site: ${result.siteUrl}`,
    `Trusted repository: ${result.repository} (branch ${result.branch})`,
    `Workflow: ${result.workflowPath} (${result.workflow})`,
    '',
    'Next steps:',
    `1. Commit and push ${result.workflowPath} to ${result.branch}.`,
    `2. Every push to ${result.branch} then deploys ${result.subdomain} through GitHub Actions. No secrets are stored in the repository.`,
    '',
    ...CLAIM_INSTRUCTIONS,
  ].join('\n');
}
